typedef float vm_num_t;
#define assert(condition) ((void)0)

class stringx
{
public:
  void* my_buf;
  char* chars;
  inline const char *data() const
  {
    assert(chars);
    return chars;
  }
};

extern stringx operator + (const stringx&, const char*);
extern stringx operator + (const stringx&, const stringx&);
extern void error(const stringx&);
extern "C" int strcmp(const char*, const char*);

class script_object
{
public:
  class instance
  {
  public:
    const stringx& get_name() const;
  };
};

class vm_executable
{
public:
  const stringx& get_fullname() const;
};

class vm_thread
{
public:
  script_object::instance* get_instance() const;
  const vm_executable* get_executable() const;
};

class vm_stack
{
public:
  int salloc;
  char* buffer;
  char* SP;
private:
  vm_thread* my_thread;
public:
  char* get_SP() const { return SP; }
  void pop(int n) { SP -= n; }
  bool push(const char* src, int n);
  vm_thread* get_thread() const { return my_thread; }
};

typedef const stringx* vm_str_t;

class script_library_class
{
public:
  class function
  {
  public:
    enum entry_t { FIRST_ENTRY, RECALL_ENTRY };
  protected:
    char* name;
  public:
    function(const char* n);
    virtual ~function();
    virtual bool operator()(vm_stack& stack, entry_t entry) = 0;
  };
};

#define SLF_PARMS \
  stack.pop(sizeof(parms_t)); \
  parms_t* parms = (parms_t*)stack.get_SP()
#define SLF_RETURN \
  if (!stack.push((char*)&result,sizeof(result)) ) \
    error( stack.get_thread()->get_instance()->get_name() + ": stack overflow in " + stack.get_thread()->get_executable()->get_fullname() )
#define SLF_DONE return true

class slf_strcmp_t : public script_library_class::function
{
  public:
    slf_strcmp_t(const char* n): script_library_class::function(n) { }
    struct parms_t
    {
      vm_str_t s1;
      vm_str_t s2;
    };
    virtual bool operator ()(vm_stack &stack, entry_t entry)
    {
      SLF_PARMS;
      vm_num_t result = strcmp( parms->s1->data(), parms->s2->data() );
      SLF_RETURN;
      SLF_DONE;
    }
};

slf_strcmp_t slf_strcmp("strcmp(str,str)");
